// Configuration
const width = 900;
const height = 800;
const margin = { top: 20, right: 20, bottom: 20, left: 20 };

// Global state
let allData = [];
let selectedTicker = null;

// Format market cap for display
function formatMarketCap(value) {
    if (!value || isNaN(value)) return 'N/A';
    const trillion = 1e12;
    const billion = 1e9;
    const million = 1e6;

    if (value >= trillion) {
        return (value / trillion).toFixed(2) + 'T';
    } else if (value >= billion) {
        return (value / billion).toFixed(2) + 'B';
    } else if (value >= million) {
        return (value / million).toFixed(2) + 'M';
    }
    return value.toFixed(0);
}

// Load and process data
d3.csv('data/stock-descriptions.csv').then(data => {
    // Process data
    allData = data.map(d => ({
        ticker: d.ticker,
        sector: d.sector || 'Unknown',
        name: d['full name'] || d.ticker,
        marketCap: +d.marketCap || null,
        isETF: !d.marketCap || d.marketCap === ''
    }));

    // Create visualizations
    createBubbleChart(allData);
    createDataTable(allData);
});

function createBubbleChart(data) {
    // Get unique sectors and create color scale
    const sectors = [...new Set(data.map(d => d.sector))].sort();
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeCategory10.concat(d3.schemePaired));

    // Create SVG
    const svg = d3.select('#bubble-chart')
        .attr('width', width)
        .attr('height', height);

    // Create tooltip
    const tooltip = d3.select('body')
        .append('div')
        .attr('class', 'tooltip');

    // Calculate bubble sizes
    const minRadius = 15;
    const maxRadius = 60;
    const etfRadius = 20;

    // Filter out ETFs for scaling
    const dataWithMarketCap = data.filter(d => !d.isETF && d.marketCap);

    const radiusScale = d3.scaleSqrt()
        .domain([0, d3.max(dataWithMarketCap, d => d.marketCap)])
        .range([minRadius, maxRadius]);

    // Add radius to data
    data.forEach(d => {
        d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap || 0);
    });

    // Create sector positions for clustering
    const sectorPositions = {};
    const sectorsPerRow = 3;
    const sectorSpacing = width / (sectorsPerRow + 1);
    const rowSpacing = height / (Math.ceil(sectors.length / sectorsPerRow) + 1);

    sectors.forEach((sector, i) => {
        const row = Math.floor(i / sectorsPerRow);
        const col = i % sectorsPerRow;
        sectorPositions[sector] = {
            x: sectorSpacing * (col + 1),
            y: rowSpacing * (row + 1)
        };
    });

    // Initialize positions
    data.forEach(d => {
        d.x = width / 2 + (Math.random() - 0.5) * 100;
        d.y = height / 2 + (Math.random() - 0.5) * 100;
    });

    // Create force simulation
    const simulation = d3.forceSimulation(data)
        .force('charge', d3.forceManyBody().strength(-5))
        .force('collision', d3.forceCollide().radius(d => d.radius + 2))
        .force('x', d3.forceX(d => sectorPositions[d.sector].x).strength(0.3))
        .force('y', d3.forceY(d => sectorPositions[d.sector].y).strength(0.3))
        .force('center', d3.forceCenter(width / 2, height / 2).strength(0.05));

    // Create bubbles
    const bubbles = svg.selectAll('.bubble')
        .data(data)
        .join('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => colorScale(d.sector))
        .attr('stroke', '#fff')
        .attr('stroke-width', 2)
        .on('mouseover', function(event, d) {
            if (!d.isETF) {
                tooltip
                    .html(`
                        <strong>${d.ticker}</strong><br/>
                        ${d.name}<br/>
                        <em>${d.sector}</em>
                    `)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 10) + 'px')
                    .classed('visible', true);
            }
        })
        .on('mouseout', function() {
            tooltip.classed('visible', false);
        })
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Create labels
    const labels = svg.selectAll('.bubble-label')
        .data(data)
        .join('text')
        .attr('class', 'bubble-label')
        .text(d => d.ticker)
        .style('font-size', d => Math.min(d.radius / 3, 12) + 'px')
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Update positions on simulation tick
    simulation.on('tick', () => {
        bubbles
            .attr('cx', d => d.x)
            .attr('cy', d => d.y);

        labels
            .attr('x', d => d.x)
            .attr('y', d => d.y + 4);
    });

    // Create legend
    const legendContainer = d3.select('#legend');
    const legendTitle = legendContainer.append('div')
        .attr('class', 'legend-title')
        .text('Sectors');

    const legendItems = legendContainer.append('div')
        .attr('class', 'legend-items');

    sectors.forEach(sector => {
        const item = legendItems.append('div')
            .attr('class', 'legend-item');

        item.append('div')
            .attr('class', 'legend-color')
            .style('background-color', colorScale(sector));

        item.append('span')
            .text(sector);
    });

    // Store references for selection
    window.bubbleElements = bubbles;
    window.labelElements = labels;
}

function createDataTable(data) {
    // Sort data by ticker
    const sortedData = [...data].sort((a, b) => a.ticker.localeCompare(b.ticker));

    const table = d3.select('#data-table');

    // Create header
    const thead = table.append('thead');
    thead.append('tr')
        .selectAll('th')
        .data(['Ticker Symbol', 'Full Company Name', 'Sector', 'Market Cap'])
        .join('th')
        .text(d => d);

    // Create body
    const tbody = table.append('tbody');
    const rows = tbody.selectAll('tr')
        .data(sortedData)
        .join('tr')
        .attr('data-ticker', d => d.ticker)
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Add cells
    rows.each(function(d) {
        const row = d3.select(this);

        row.append('td')
            .attr('class', 'ticker-cell')
            .text(d.ticker);

        row.append('td')
            .text(d.name);

        row.append('td')
            .attr('class', 'sector-cell')
            .text(d.sector);

        row.append('td')
            .attr('class', 'marketcap-cell')
            .text(formatMarketCap(d.marketCap));
    });

    // Store reference for selection
    window.tableRows = rows;
}

function selectStock(ticker) {
    // Update selected ticker
    if (selectedTicker === ticker) {
        selectedTicker = null;
    } else {
        selectedTicker = ticker;
    }

    // Update bubble selection
    if (window.bubbleElements) {
        window.bubbleElements.classed('selected', d => d.ticker === selectedTicker);
    }

    // Update table selection
    if (window.tableRows) {
        window.tableRows.classed('selected', d => d.ticker === selectedTicker);

        // Scroll to selected row
        if (selectedTicker) {
            const selectedRow = d3.select(`tr[data-ticker="${selectedTicker}"]`).node();
            if (selectedRow) {
                selectedRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }
}
EOF
